SELECT

FROM `order`
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE `order`
SET status = #{status}, pay_time = #{payTime}, updated_at = #{updatedAt}, update_by = #{updateBy}
WHERE id = #{id} AND user_id = #{userId}

UPDATE `order`
SET status = #{status}, pay_time = #{payTime}, updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{expectedStatus}
